/* Growth edition: local-first learning and family adventures. */
window.Growth=(()=>{
'use strict';
const X=window.Expedition,C=window.GROWTH_CONTENT,W=window.WORLDS,P=window.QuestProgress,S=window.QuestSound,G=window.Grandma;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
const B=(label,action,cls='btn-green',extra='')=>`<button class="btn ${cls}" data-growth="${action}" ${extra}>${label}</button>`;
const today=()=>P.day();let cueKey='',lastSpoken='',A,s,g,active=null,selected=-1,viewAt=0,qSession='',questionAt=0,wordTask=null,miniTask=null,battleTask=null,ink=null;
const PATHS=[
[{label:'Read the shore',lead:'Follow Maya along the harbour path.',text:'Maya shows you two drawings. In the first, a rock is covered by water. In the second, the same rock is exposed. You compare the rock, not the colour of the sky. You stay on the path and sketch what changed.',q:'Which detail best shows the water level changed?',options:['The same rock is exposed in one drawing','Both drawings have blue sky','Maya uses a pencil'],answer:0,power:'shield',find:'Tide detective',token:'A wave and a rock'},
{label:'Help the boat maker',lead:'Visit Rowan’s safe model-making table.',text:'Rowan folds a small paper boat. It tips when all three toy counters sit on one side. You suggest spreading the counters across the boat. The second model stays more level. You test on a tray, not in the harbour.',q:'What change made the boat model more level?',options:['Using a louder voice','Spreading the counters across the boat','Putting every counter on one side'],answer:1,power:'magnet',find:'Boat tester',token:'A folded boat'}],
[{label:'Follow the leaf',lead:'Explore Hana’s garden path.',text:'Hana gives you a leaf drawing with a pointed tip and one long middle vein. You compare it with two leaves on a picture board. One is round; the other has both matching features. You do not pull leaves from the garden.',q:'Which leaf is the stronger match?',options:['Any green leaf','The round leaf','The leaf with a pointed tip and long middle vein'],answer:2,power:'shield',find:'Leaf observer',token:'A pointed leaf'},
{label:'Repair a lantern',lead:'Help Aki at the craft table.',text:'Aki has a thin paper lantern and a cloth bag. Pulling on the paper makes a small tear larger. You ask Aki to hold the lantern while you open the bag. Sharing two jobs protects the paper.',q:'Which plan best protects the lantern?',options:['Ask Aki to hold it while you open the bag','Pull harder on the torn edge','Leave it in the stream'],answer:0,power:'magnet',find:'Lantern helper',token:'A paper lantern'}],
[{label:'Test a stone arch',lead:'Try Sofia’s tabletop model.',text:'A toy arch falls when one middle piece is missing. You compare it with a complete model. You replace the missing piece and test gently. The model stands this time. You leave the real ancient stones alone.',q:'What did the comparison help you find?',options:['A pizza ingredient','The missing middle piece','A river current'],answer:1,power:'shield',find:'Model scientist',token:'A fitted stone'},
{label:'Follow the basil',lead:'Visit Luca’s ingredient table.',text:'Luca has a green basil leaf, a tomato, and cheese. You sort each into a picture group. Basil and tomato go in the plant group. Cheese has a different origin. You ask before touching or tasting.',q:'Which two ingredients belong in the plant group?',options:['Basil and cheese','Cheese and a milk jug','Basil and tomato'],answer:2,power:'magnet',find:'Ingredient investigator',token:'A basil leaf'}],
[{label:'Decode the map',lead:'Study Nour’s map key.',text:'Nour’s map uses a blue line for water and a dotted line for a walking path. One route is solid blue; the other is dotted. You check the key before suggesting the dotted route for a walk with your grown-up.',q:'Why do you choose the dotted route for the walk?',options:['The key says dots show a walking path','Blue always means a safe footpath','Dots make the journey shorter'],answer:0,power:'shield',find:'Map decoder',token:'A dotted trail'},
{label:'Solve the wind puzzle',lead:'Work with Omar at a picnic bench.',text:'Two corners of a map lift in the breeze. Omar has two paperweights and one folder. You hold the map flat while he places a weight on each loose corner. Then you slide the map into the folder together.',q:'Why is this a two-person plan?',options:['Two people can stop all wind','One keeps the map flat while the other secures it','Maps can only be read by two people'],answer:1,power:'magnet',find:'Wind-wise helper',token:'A protected map'}],
[{label:'Care for a plant',lead:'Join Lucía beside the plant pots.',text:'Lucía has two pots. One saucer is already full of water; the other has dry soil at the top. You ask her to check the plants’ needs before adding anything. Different conditions call for different decisions.',q:'What is the best next action?',options:['Pour a bucket into both pots','Ignore the soil and the saucers','Ask Lucía to check what each plant needs'],answer:2,power:'shield',find:'Plant carer',token:'A root sketch'},
{label:'Complete the pattern',lead:'Help Inti sort woven colour cards.',text:'The cards go gold, green, gold, green. One card is missing at the end. You say the sequence aloud in pairs and choose gold next. Explaining the repeating unit is stronger than saying a colour at random.',q:'What repeating unit explains the next gold card?',options:['Gold, green','Gold, gold, green','Every third card is blue'],answer:0,power:'magnet',find:'Pattern finder',token:'A woven pair'}],
[{label:'Protect the harbour',lead:'Take a ranger’s path with Jess.',text:'A clean plastic bottle lies on the wide path. A sharp, unknown object is closer to the water. You ask Jess for help. She handles the unsafe item; you help with the bottle only when she says it is safe.',q:'Which plan is safest?',options:['Pick up every unknown object alone','Ask Jess and leave unsafe items to the grown-up','Climb down the harbour edge'],answer:1,power:'shield',find:'Harbour guardian',token:'A clean shoreline'},
{label:'Match the roof clues',lead:'Study Taylor’s picture folder.',text:'Taylor shows you a roof drawing, a harbour photograph, and a note that says Sydney. A different photograph has a white roof but no harbour. You keep the clues that agree with one another rather than matching colour alone.',q:'Which set gives the strongest location evidence?',options:['One white patch','A random roof from another picture','The roof drawing, harbour photo, and Sydney note together'],answer:2,power:'magnet',find:'Clue connector',token:'A sail-shaped roof'}]
];
const CASES=[
{clues:['A city in Japan','A red bridge','A paper lantern'],q:'Where should the atlas team travel next?',options:['Rome, Italy','Kyoto, Japan','Cairo, Egypt'],answer:1,next:1},
{clues:['A city in Italy','An arch of fitted stones','A picture of a bowl'],q:'Which next city fits the country and stone-arch note?',options:['Sydney, Australia','Cusco, Peru','Rome, Italy'],answer:2,next:2},
{clues:['A city in Egypt','A long river','The word Nile'],q:'Where do these three clues point?',options:['Cairo, Egypt','Kyoto, Japan','Cusco, Peru'],answer:0,next:3},
{clues:['A city in Peru','High in the Andes','A mountain drawing'],q:'Which place fits all three clues?',options:['Rome, Italy','Cusco, Peru','Sydney, Australia'],answer:1,next:4},
{clues:['A city in Australia','A harbour','A white, sail-shaped roof'],q:'Which place is the next atlas destination?',options:['Kyoto, Japan','Cairo, Egypt','Sydney, Australia'],answer:2,next:5},
{clues:['Six rescued atlas pages','Clues checked against evidence','A new question to explore with family'],q:'What is the best plan after finishing the atlas?',options:['Explore a safe place with family and keep asking questions','Stop exploring because learning is finished','Only choose things that are already easy'],answer:0,next:null}
];
let saveTimer=0;function queueSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{if(s)P.save();},350);}
function boot(api){A=api;s=A.state;P.attach(s,()=>{g=s.g;active=null;wordTask=null;miniTask=null;battleTask=null;A.stats();A.nav('trail');});g=s.g;apply();
for(let i=0;i<6;i++)for(let n=0;n<3;n++)W[i].quests[n].title=C.quests[i][n].title;
X.boot({state:()=>s,progress:()=>g,award:(xp,pts)=>award(xp,pts),save,draw:()=>{if(active?.kind==='story')drawStory();},shell,speak,story:()=>active,continue:continueQuest,quest:(n,l)=>quest(n,l),record:()=>rec()});document.addEventListener('click',click);document.addEventListener('change',change);document.addEventListener('input',input);
document.addEventListener('questsaved',saveIndicator);document.addEventListener('questvoice',()=>{$$('[data-growth="pause-voice"]').forEach(b=>{b.innerHTML=I(S.state().paused?'play':'pause')+(S.state().paused?' Resume voice':' Pause voice');});});
window.addEventListener('blur',()=>P.save());setInterval(()=>{if(!document.hidden&&s.g===g&&active?.kind==='story'&&Date.now()-g.lastBreak>g.breakMinutes*60000){$('#growth-break-nudge')?.remove();$('.g-body')?.insertAdjacentHTML('beforeend',`<div id="growth-break-nudge" class="g-note">A movement break is ready when you are. ${B('Stretch or breathe','break','btn-plain')}</div>`);}},30000);
}
function save(){g=s.g;P.save();apply();}
function apply(){const pc=$('#pts-count');if(pc)pc.textContent=g.trailPoints;document.body.classList.toggle('reading-window',!!g.window);document.body.classList.toggle('reading-ruler',!!g.ruler);document.documentElement.style.setProperty('--growth-font-scale',g.fontScale||1);$$('.profile strong').forEach(e=>e.textContent=P.status().profile);$$('.profile-letter').forEach(e=>e.textContent=P.status().profile.charAt(0));}
function saveIndicator(){const el=$('#growth-save-status');if(el)el.textContent=P.status().storageOK?'Saved on this device':'Keep a backup code';}
function penalty(fast){const cost=fast?7:5;g.trailPoints=Math.max(0,g.trailPoints-cost);save();return cost;}
function activity(){g.activities++;g.lastActivity=today();const key=today();g.goals[key]=g.goals[key]||{stories:0,words:0,movement:false};save();}
function award(xp,points=0){s.xp+=xp;g.trailPoints+=points;A.stats();save();}
function evidenceIds(q){return [q.evidence,(q.evidence+2)%6,(q.evidence+4)%6].sort((a,b)=>((a+2)%6)-((b+2)%6));}
function shell(title,sub,html,type='growth',wide=false){A.showModal(`<section class="modal growth-modal ${wide?'g-wide':''}" role="dialog" aria-modal="true" aria-labelledby="g-title">${A.closeButton()}<div class="g-head"><span class="eyebrow">${E(sub)}</span><h2 id="g-title">${E(title)}</h2></div><div class="g-body">${html}</div></section>`,type);A.icons();}
function speak(text,id,quiet){if(!s.sound||!s.voice){if(!quiet)A.toast('Voice is off. Turn it on in Sound settings, then try again.');return}S.boot();if(id){S.narrate(id,{error:()=>{if(S.speak)S.speak(text,{rate:g.rate,error:()=>A.toast('Voice is unavailable here. All text remains on screen.')});else A.toast('Voice is unavailable here. All text remains on screen.');}});}else if(S.speak)S.speak(text,{rate:g.rate,error:()=>A.toast('A device voice is unavailable. You can still read or ask a grown-up.')});else A.toast('All text is on screen. A device voice is unavailable here.');}
function tools(text,id){return `<div class="g-tools">${B(I('volume-2')+' Read to me','speak','btn-plain',`data-text="${E(text)}" ${id?`data-audio="${id}"`:''}`)}${B(I('pause')+' Pause voice','pause-voice','btn-plain')}${B(I('book-open')+' Reread','reread','btn-plain')}${B(I('lightbulb')+' Help','help','btn-plain')}${B(I('coffee')+' Break','break','btn-plain')}</div>`;}
function strip(){const pages=Object.values(g.atlas).filter(Boolean).length;return `<section class="growth-strip"><div class="atlas-mark">${I('notebook-tabs')}<span>${pages}/6</span></div><div><span class="eyebrow">THE ATLAS OF WONDER</span><h2>Six missing pages. One curious team.</h2><p>Explore a place. Solve a field mission. Discover the secret.</p><div class="growth-chips"><span>${X.rank()}</span><span>${X.count()}/18 discoveries</span><span>${s.done}/18 keys</span><span>${g.trailPoints} trail points</span><span id="growth-save-status">${P.status().storageOK?'Saved on this device':'Keep a backup code'}</span></div></div><div class="g-stack">${B(I('compass')+' Continue adventure','continue','btn-primary')}${B(I('book-marked')+' Nature Dex','exp-dex','btn-plain')}</div></section>`;}
function decorateTrail(){const main=$('#main');$('.page-heading',main)?.insertAdjacentHTML('afterend',strip());const h=$('.page-heading h1',main);if(h)h.textContent=`The world is waiting, ${P.status().profile}.`;A.icons();saveIndicator();}
function decorateArea(){const i=s.level;const done=[0,1,2].filter(n=>g.discoveries?.[i+'-'+n]).length;$('.area-heading')?.insertAdjacentHTML('afterend',`<div class="g-area-banner"><span>${I('flask-conical')} ${done}/3 field missions solved here · ${X.count()}/18 discoveries · ${E(X.rank())}</span>${B(I('book-marked')+' Nature Dex','exp-dex','btn-plain')}${s.done>=(i+1)*3?B('Connect the atlas clues','case','btn-primary',`data-lv="${i}"`):''}</div>`);A.icons();}
function decoratePassport(){const p=$('.pass-summary');p?.insertAdjacentHTML('afterend',`<div class="g-note">${Object.values(g.atlas).filter(Boolean).length}/6 atlas pages recovered · ${Object.keys(g.field).length} route discoveries · ${Object.values(g.wordRecords).filter(r=>r.dates?.length>=2).length} words recalled on two or more days. ${B('Visit basecamp','camp','btn-plain')}</div>`);$$('.journal-line').forEach(e=>{if(e.textContent.includes('Tasted '))e.innerHTML=e.innerHTML.replace('Tasted <strong>','Discovered <strong>');});A.icons();}
function continueQuest(){A.nav('area',Math.min(5,Math.floor(s.done/3)));if(s.done<18)quest(s.done%3);else camp();}
function quest(n,level=s.level,review=false){if(n>Math.max(0,s.done-level*3)){A.toast('Finish the glowing story first.');return}
const id=level+'-'+n;let r=g.ledger[id];if(!r){r=g.ledger[id]={page:0,stage:'read',tries:0,wrongs:0,variant:g.tier>=2?1:0,scored:false,key:level*3+n<s.done,events:[],readMs:0,created:today(),seen:[]};}
active={kind:'story',level,n,id,r,review,replay:level*3+n<s.done};if(review){active.reviewFresh=true;active.reviewRecord={page:0,stage:'read',tries:0,wrongs:0,variant:r.variant===1?0:1,scored:false,key:true,events:[],seen:[],readMs:0};}
selected=-1;qSession='';drawStory();}
function rec(){return active.reviewFresh?active.reviewRecord:active.r;}
function storyQ(){return C.quests[active.level][active.n].questions[rec().variant];}
function drawStory(){const t=active,r=rec(),q=C.quests[t.level][t.n],w=W[t.level],x=storyQ();const page=r.page||0;viewAt=Date.now();
const k=t.id+'-'+r.tries+'-'+r.stage+'-'+r.variant;if(k!==qSession){qSession=k;questionAt=Date.now();selected=-1;}
let body='';
const stepNo=r.stage==='read'?0:r.stage==='lab'?1:r.stage==='check'||r.stage==='review'||r.stage==='evidence'||r.stage==='guided'?2:3;const steps=`<div class="g-steps" aria-label="Explore, experiment, decode, discover">${['Explore','Experiment','Decode','Discover'].map((z,i)=>`<span class="${stepNo===i?'current':i<stepNo?'past':''}">${z}</span>`).join('')}</div>`;
if(t.reread!==undefined&&t.reread!==null){const pg=t.reread;body=`<div class="g-chunk-meta"><span>STORY CARD ${pg+1} OF 3</span><span>Reading again. No score, no timer.</span></div><div class="g-passage" data-page="${pg}">${q.sentences.slice(pg*2,pg*2+2).map((v,i)=>`<p data-line="${i}">${E(v)}</p>`).join('')}</div>${tools(q.chunks[pg],`g-${t.level}-${t.n}-${pg}`)}<div class="g-actions">${pg>0?B(I('arrow-left')+' Previous card','reread-prev','btn-plain'):''}${B(pg<2?'Next story card '+I('arrow-right'):'Back to my key','reread-next','btn-primary')}</div>`;}
else if(r.stage==='read')body=`<div class="g-chunk-meta"><span>STORY CARD ${page+1} OF 3</span><span>Listen or read. Your pace.</span></div><div class="g-passage" data-page="${page}">${q.sentences.slice(page*2,page*2+2).map((v,i)=>`<p data-line="${i}">${E(v)}</p>`).join('')}</div>${tools(q.chunks[page],`g-${t.level}-${t.n}-${page}`)}<div class="g-actions">${page>0?B(I('arrow-left')+' Previous card','prev-page','btn-plain'):''}${B(page<2?'Next story card '+I('arrow-right'):(t.review||X.lab(t)&&g.labs?.[t.id]?.done?'Decode the clue ':'Start the field mission ')+I('arrow-right'),'next-page','btn-primary')}</div>`;
else if(r.stage==='lab')body=X.renderLab(t);
else if(r.stage==='check')body=`<div class="g-task-title"><span class="g-qtype g-qtype-${E((x.kind||'WHAT').toLowerCase())}">${E(x.kind||'WHAT')}</span><span class="eyebrow">${g.tier>=2?'CONNECT THE DETAILS':'FIND THE DETAIL'}</span><h3>${E(x.q)}</h3><p class="g-q-hint">${E(x.hint||'')} Check story card ${Math.floor(x.evidence/2)+1} if you need it.</p></div>${tools(x.q+' A. '+x.options[0]+'. B. '+x.options[1]+'. C. '+x.options[2]+'.',`gq-${t.level}-${t.n}-${r.variant}`)}<div class="g-options">${x.options.map((v,i)=>`<button class="g-option ${selected===i?'selected':''}" data-growth="select-answer" data-value="${i}" aria-pressed="${selected===i}"><b>${'ABC'[i]}</b><span>${E(v)}</span>${selected===i?I('check'):''}</button>`).join('')}</div><div class="g-actions">${B('Lock in my answer '+I('arrow-right'),'commit-answer','btn-primary',selected<0?'disabled':'')}${B(I('book-open')+' Look back at the story','peek','btn-plain')}</div><details class="g-score-note"><summary>How points work</summary><p>Think first, then lock in. Fast guesses and wrong locks cost a few trail points, never your keys or XP already earned. Listening and looking back cost nothing.</p></details>`;
else if(r.stage==='evidence')body=`<div class="g-feedback success">${I('check')} That answer fits. One more step.</div><h3>Tap the sentence that proves it.</h3><p class="g-small">Your answer: <strong>${E(x.options[x.answer])}</strong></p>${tools('Which sentence supports your answer? Choose the detail that explains why.')}<div class="g-options evidence-options">${evidenceIds(x).map((idx,i)=>`<button class="g-option ${selected===idx?'selected':''}" data-growth="select-evidence" data-value="${idx}" aria-pressed="${selected===idx}"><b>${i+1}</b><span>${E(q.sentences[idx])}</span></button>`).join('')}</div><div class="g-actions">${B('Explain my choice '+I('arrow-right'),'commit-evidence','btn-primary',selected<0?'disabled':'')}</div>`;
else if(r.stage==='review')body=`<div class="g-feedback">${I('search')} ${r.fast?'That quick guess missed a detail. Pause, check the clue, and build a new plan.':'This detail changes the answer. Let’s look closely.'}</div><h3>Study the evidence</h3><blockquote class="g-evidence">${E(q.sentences[x.evidence])}</blockquote><p>The supported answer is <strong>${E(x.options[x.answer])}</strong>.</p>${B(I('volume-2')+' Read this story card','speak','btn-plain',`data-text="${E(q.chunks[Math.floor(x.evidence/2)])}" data-audio="g-${t.level}-${t.n}-${Math.floor(x.evidence/2)}"`)}<p class="g-small">This key is still available. This story’s XP and trail-point bonus are now locked, including after a reload. ${r.lastCost||5} trail points were deducted; earned XP and keys are safe.</p><div class="g-actions">${B(r.wrongs<2?'I found the clue. Give me a different question.':'Solve it with a model.','after-review','btn-primary')}</div>`;
else if(r.stage==='guided')body=`<span class="eyebrow">WORKED EXAMPLE · LEARN, THEN CONTINUE</span><h3>Build an explanation with me.</h3><p>Question: ${E(x.q)}</p><blockquote class="g-evidence">${E(q.sentences[x.evidence])}</blockquote><p>That detail supports: <strong>${E(x.options[x.answer])}</strong>.</p><p>Choose the sentence we used in this explanation. This is guided practice, not a scored answer.</p><div class="g-options">${evidenceIds(x).map((idx,i)=>`<button class="g-option" data-growth="guided-evidence" data-value="${idx}"><b>${i+1}</b><span>${E(q.sentences[idx])}</span></button>`).join('')}</div><div class="g-inline-message" role="status"></div>`;
else {const earned=r.xpEarned||0;body=`<div class="g-reward"><span class="g-big-key">${I('key-round')}</span><span class="eyebrow">${t.review?'REVIEW COMPLETE':t.replay&&r.created!==today()?'A KEY ALREADY KEPT':'YOUR PROGRESS IS SAFE'}</span><h3>${t.review?'You came back to a useful clue.':'Golden key collected.'}</h3><p>${r.wrongs?'You used feedback and a model to finish. That is a useful learning strategy.':r.hinted?'You used a helpful clue and explained your answer. Tools belong in your toolkit.':'You connected an answer to its evidence.'}</p><p><strong>${earned?`+${earned} XP`:'No XP for this practice completion'}</strong>${r.pointsEarned?` · +${r.pointsEarned} trail points`:''}</p>${t.review?'':X.renderDiscovery(t)}${t.replay&&!t.review?'<p class="g-small">Reopening a completed story cannot earn its reward twice.</p>':''}<div class="g-actions">${B(t.review?'Back to basecamp':t.n===2?`Meet ${w.pet}`:'Next scene '+I('arrow-right'),'finish-story','btn-primary')}${B(I('puzzle')+' Word forge','words','btn-plain')}${B(I('zap')+' Key-power run','dash','btn-plain',`data-lv="${t.level}"`)}${t.review?'':B(I('book-open')+' Read it again','reread','btn-plain')}</div></div>`;}
const art=t.n===0?`char-${w.id}.webp`:t.n===1?`food-${w.id}.webp`:`pokemon/${w.petId}.webp`;
A.showModal(`<section class="modal growth-story" role="dialog" aria-modal="true" aria-labelledby="g-title">${A.closeButton()}<aside class="g-story-art"><img class="g-bg" src="assets/bg-${w.id}.webp" alt=""><img class="g-character g-art-${t.n}" src="assets/${art}" alt="${E(t.n===0?w.npc:t.n===1?w.food:w.pet)}"><span class="g-location">${E(w.country)} · ${E(w.place)}</span><div class="g-art-caption"><span>THE ATLAS OF WONDER</span><strong>${['People leave clues.','Look. Ask. Discover.','Make room for a friend.'][t.n]}</strong></div></aside><div class="g-story-copy"><div class="g-head"><span class="eyebrow">${t.review?'SPACED REVIEW':`LEVEL ${t.level+1} · QUEST ${t.n+1}`} · ${E(w.place)}</span><h2 id="g-title">${E(q.title)}</h2>${steps}</div><div class="g-body">${body}</div></div></section>`,'growth-story');A.icons();save();
if(r.stage==='read'&&cueKey!==t.id+'-'+page&&!t.reread&&t.reread!==0){cueKey=t.id+'-'+page;S.cue(t.level,t.n,page);}
if(r.stage==='read'&&s.autoRead&&lastSpoken!==t.id+'-'+page){lastSpoken=t.id+'-'+page;speak(q.chunks[page],`g-${t.level}-${t.n}-${page}`,true);}
}
function wrongAnswer(part){const r=rec(),fast=Date.now()-questionAt<2500||(r.readMs||0)<6000&&!r.hinted;r.wrongs++;r.tries++;r.fast=fast;r.lastCost=penalty(fast);r.events.push({date:today(),part,correct:false,fast});r.stage='review';schedule('q:'+active.id,false);save();S.sfx('gentle');selected=-1;drawStory();G.react(fast?'rapid':'wrong');}
function finishKey(){const t=active,r=rec(),absolute=t.level*3+t.n;let xp=0,points=0;if(t.review){const review=g.reviews['q:'+t.id];if(r.wrongs===0&&review?.paid!==today()){xp=5;points=5;if(review)review.paid=today();}schedule('q:'+t.id,r.wrongs===0);}
else if(!r.scored){if(!t.replay&&r.wrongs===0){xp=20;points=20;}r.scored=true;if(absolute===s.done){s.done++;if(t.n===2&&s.buddy<0)s.buddy=t.level;}if(!t.replay){g.goals[today()]=g.goals[today()]||{stories:0,words:0,movement:false};g.goals[today()].stories++;}schedule('q:'+t.id,r.wrongs===0);}
r.xpEarned=xp;r.pointsEarned=points;r.key=true;r.stage='done';r.completed=today();activity();award(xp,points);adapt();drawStory();S.celebrate(t.review?2:3);G.go(t.review?2:3);G.react('cheer');}
function adapt(){if(!g.adaptive)return;const r=Object.values(g.ledger).filter(r=>r.stage==='done').slice(-5);if(r.length<4)return;const clear=r.filter(r=>r.wrongs===0).length;if(clear>=4)g.tier=3;else if(clear<=1)g.tier=1;else g.tier=2;save();}
function schedule(id,good){const r=g.reviews[id]||{step:0,due:0,paid:'',lastActivity:0};r.step=good?Math.min(4,r.step+1):0;r.due=Date.now()+([1,3,7,14,30][r.step])*P.dayMs;if(!good)r.due=Date.now();r.lastActivity=g.activities;r.correct=good;g.reviews[id]=r;save();}
function due(){return Object.entries(g.reviews).filter(([id,r])=>r.due<=Date.now()&&(r.correct||g.activities>=r.lastActivity+2||r.due<Date.now()-P.dayMs));}
function path(level,after){if(level*3>s.done){A.toast('This destination is still locked.');return;}const chosen=g.paths[level];if(chosen!==undefined){field(level);return;}active={kind:'path',level,after};shell('Which lead will you follow?',W[level].country+' · YOUR CHOICE CHANGES YOUR DISCOVERY',`<p>Both routes continue the atlas story. Each brings a different field challenge and a different Trail Dash tool.</p><div class="g-route-grid">${PATHS[level].map((p,i)=>`<button class="g-route-card" data-growth="choose-path" data-value="${i}"><span class="g-route-symbol">${I(p.power==='shield'?'leaf':'hammer')}</span><h3>${E(p.label)}</h3><p>${E(p.lead)}</p><strong>${p.power==='shield'?'Earn a one-bump field shield':'Earn a wider pickup magnet'}</strong>${I('arrow-right')}</button>`).join('')}</div><div class="g-note">Your choice is saved with your adventure. Your discovery and runner tool come from the path you choose.</div>`,'growth');}
function field(i){const p=PATHS[i][g.paths[i]??0];mini({key:'field-'+i,title:p.label,eyebrow:W[i].country+' · FIELD MISSION',text:p.text,q:p.q,options:p.options,answer:p.answer,xp:10,done:()=>{g.field[i]={power:p.power,find:p.find,token:p.token};save();},ending:`${p.find} discovery collected. ${p.power==='shield'?'Your field shield absorbs one collision on each run.':'Your pickup magnet reaches more nearby treasure on each run.'}`});}
function caseMission(i){G.say('coach-map',{once:true,cool:20000});if(s.done<(i+1)*3){A.toast('Collect this destination’s three story keys to open its case.');return;}const c=CASES[i];mini({key:'atlas-'+i,title:i===5?'Bring the atlas home':'Where in the world next?',eyebrow:'ATLAS CASE '+(i+1)+' OF 6',text:'Compare the notes from your journey. '+c.clues.join('. ')+'.',q:c.q,options:c.options,answer:c.answer,xp:10,clues:c.clues,done:()=>{g.atlas[i]=true;save();},ending:i===5?'All six atlas pages can now fit together. Your family mission book holds the next adventures.':`An atlas page is restored. ${W[c.next].place} is your next lead.`});}
function mini(task){miniTask=task;const r=g.goals[task.key]||{stage:'ready',choice:-1,wrong:false,paid:false};g.goals[task.key]=r;selected=r.choice??-1;active={kind:'mini',key:task.key};drawMini();}
function drawMini(){const t=miniTask,r=g.goals[t.key];let body=`${t.clues?`<div class="g-clue-row">${t.clues.map((x,i)=>`<div><b>CLUE ${i+1}</b><span>${E(x)}</span></div>`).join('')}</div>`:`<div class="g-passage"><p>${E(t.text)}</p></div>`}${B(I('volume-2')+' Read to me','speak','btn-plain',`data-text="${E(t.text+' '+t.q+' '+t.options.map((x,i)=>'ABC'[i]+'. '+x).join('. '))}"`)}<h3>${E(t.q)}</h3>`;
if(r.stage==='ready')body+=`<div class="g-options">${t.options.map((v,i)=>`<button class="g-option ${selected===i?'selected':''}" data-growth="mini-select" data-value="${i}" aria-pressed="${selected===i}"><b>${'ABC'[i]}</b><span>${E(v)}</span></button>`).join('')}</div>${B('Use this evidence','mini-commit','btn-primary',selected<0?'disabled':'')}<p class="g-small">One committed answer. After a mistake, review the explanation; no score is awarded for clicking through choices.</p>`;
else if(r.stage==='review')body+=`<div class="g-feedback">Let’s connect the detail to the answer.</div><blockquote class="g-evidence">${E(t.text)}</blockquote><p>The supported answer is <strong>${E(t.options[t.answer])}</strong>. No XP is awarded for this guided completion.</p>${B('I reviewed the explanation','mini-finish','btn-green')}`;
else body=`<div class="g-reward"><span class="g-big-key">${I(t.key.startsWith('atlas')?'notebook-tabs':'badge-check')}</span><h3>${r.wrong?'Discovery through guided practice.':'Evidence connected.'}</h3><p>${E(t.ending||'You used the story to make a decision.')}</p><p>${r.wrong?'No XP for this practice completion.':r.paid?`${r.xp||0} XP recorded for the first completion.`:'Already in your collection.'}</p><div class="g-actions">${B('Back to exploring','mini-exit','btn-primary')}${B('Visit basecamp','camp','btn-plain')}</div></div>`;
shell(t.title,t.eyebrow,body);save();}
function finishMini(){const t=miniTask,r=g.goals[t.key];if(!r.paid){r.xp=r.wrong?0:t.xp;r.paid=true;award(r.xp,r.xp);t.done?.();activity();}r.stage='done';save();drawMini();S.sfx('match');}
function guide(i){const a=A.guides[i],answers=[a.role,'an ocean pilot','a mountain climber'];const ans=(i+1)%3;[answers[0],answers[ans]]=[answers[ans],answers[0]];mini({key:'guide-'+i,title:'Meet '+a.name,eyebrow:W[i].country+' · A LOCAL FRIEND',text:a.text,q:`Which role explains ${a.name}’s work in this story?`,options:answers,answer:ans,xp:s.side[i]?0:30,done:()=>{s.side[i]=true;save();},ending:`${a.name}’s local-friend sticker is in your passport.`});}
function starterOpen(){return g.openWordBank?18:Math.min(18,3+s.done);}
function trailOpen(){if(g.openWordBank)return Math.max(0,C.words.length-18);const solid=Object.entries(g.wordRecords).filter(([i,r])=>+i<18&&r.independent>0).length;return solid>=6?Math.min(C.words.length-18,Math.max(2,s.done-3)):0;}
function wordLimit(){return starterOpen()+trailOpen();}
function wordUnlocked(i){return i<18?i<starterOpen():i-18<trailOpen();}
function words(){active={kind:'words'};const n=wordLimit();G.say('coach-word',{once:true,cool:15000});shell('The word forge','SOUNDS INTO WORDS · WORDS INTO ADVENTURES',`<p>Hear a word, learn its letter teams, build it, then use it in your world. Practice is short and you can stop whenever you need.</p>${[0,18].map(start=>`<h3 class="g-pack-title">${start?'Trail words · a bigger challenge':'Starter words'}</h3>${start?`<p class="g-small">${trailOpen()?'These words have more letter teams, silent letters, and word parts, with a few extra tiles to think about.':'Build 6 starter words on your own to open the Trail words.'}</p>`:''}<div class="g-word-grid">${C.words.map((w,i)=>({w,i})).filter(o=>start?o.i>=18:o.i<18).map(({w,i})=>{const r=g.wordRecords[i],ok=wordUnlocked(i);return `<button class="g-word-card ${ok?'':'locked'} ${i>=18?'trail':''}" data-growth="word-open" data-value="${i}" ${ok?'':'disabled'}><span>${ok?(r?.dates?.length>=2?I('sparkles'):I('puzzle')):I('lock-keyhole')}</span><strong>${ok?E(w.word):'Next tools'}</strong><small>${ok?E(w.pattern):'More story keys open this pack'}</small><span>${r?`${r.dates?.length||0} recall days`:'Ready to discover'}</span></button>`}).join('')}</div>`).join('')}<div class="g-note">A useful pattern, not a special font, does the teaching. Sound-and-letter modelling, cumulative practice, and revisiting words are built in. A grown-up can open the whole word bank in the parent view.</div>`,'growth',true);}
function wordOpen(i,review=false){if(!wordUnlocked(i)&&!review)return;const r=g.wordRecords[i]||{attempts:0,independent:0,dates:[],helped:0,firstPaid:false};g.wordRecords[i]=r;wordTask={i,stage:r.attempts?'build':'model',built:[],wrong:false,helped:false,showModel:false,review,typed:'',order:[],firstTry:true};const ws=C.words[i];const pool=[...ws.tiles,...(ws.extra||[]).slice(0,g.tier>=2?2:1)];wordTask.order=pool.map((x,i)=>({x,id:i})).sort((a,b)=>((a.id*7+3)%11)-((b.id*7+3)%11));active={kind:'word',i};drawWord();if(s.autoRead)speak(ws.word+'. '+ws.teach+'. '+ws.meaning,'word-'+i,true);}
function drawWord(){const t=wordTask,w=C.words[t.i],r=g.wordRecords[t.i];let body='';
if(t.stage==='model')body=`<div class="g-word-model">${w.tiles.map((x,i)=>`<span class="${x.length>1?'team':''}">${E(x)}${x.length>1?'<small>letter team</small>':''}</span>`).join('')}</div><h3>${E(w.teach)}</h3><p>${E(w.meaning)}</p>${B(I('volume-2')+' Hear the model','word-listen','btn-plain')}${B('Ready to build it','word-build','btn-primary')}`;
else if(t.stage==='build')body=`<div class="g-tools">${B(I('volume-2')+' Hear the word','word-listen','btn-primary')}${B(I('eye')+' Show the model','word-model','btn-plain')}${B(I('undo-2')+' Undo a tile','word-undo','btn-plain')}</div>${t.showModel?`<div class="g-model-peek"><strong>${E(w.word)}</strong><p>${E(w.teach)}</p></div>`:''}<div class="g-sound-boxes" aria-label="Your word">${w.tiles.map((x,i)=>`<span class="${x.length>1?'team':''}">${E(t.built[i]?.x||'')}</span>`).join('')}</div><p class="g-small">Each box holds a letter or a letter team. Tap in order. ${w.extra?'Some extra tiles are decoys, so listen before you choose. ':''}You can also type the whole word.</p><div class="g-tile-bank">${t.order.map(x=>`<button class="g-letter-tile" data-growth="tile" data-value="${x.id}" ${t.built.some(z=>z.id===x.id)?'disabled':''}>${E(x.x)}</button>`).join('')}</div><label class="g-label">Or type your word<input id="g-word-input" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" value="${E(t.typed)}" placeholder="Type instead of using tiles"></label><div class="g-actions">${B('Check my word','word-check','btn-primary')}${B('Back to the word bank','words','btn-plain')}</div><div class="g-inline-message" role="status">${t.wrong?'Let’s use a model. Compare the letter teams, then rebuild. This attempt is practice with no XP.':''}</div>`;
else if(t.stage==='success')body=`<div class="g-reward"><span class="g-big-key">${I('sparkles')}</span><h3>${E(w.word)}</h3><p>${E(w.meaning)}</p><p>${t.wrong?'You compared the model and rebuilt the word. No XP for this guided attempt.':t.reward?`+${t.reward} XP for a first-try build. Listening and models are welcome.`:'Practice recorded. This word’s first-completion reward is already kept.'}</p><p class="g-small">${r.dates.length} recall ${r.dates.length===1?"day":"days"} so far. Two days is a practice milestone, not a diagnosis or a mastery assessment.</p><div class="g-actions">${B(I('pencil')+' Write or trace','word-ink','btn-primary')}${B('Another word','word-next','btn-green')}${B('Back to basecamp','camp','btn-plain')}</div></div>`;
else body=`<p>Say <strong>${E(w.word)}</strong>. Follow the pale model with a finger, stylus, or mouse. Start each letter as your teacher shows you. Ink is practice, not automatically graded.</p><canvas id="g-ink" width="1000" height="300" aria-label="Optional tracing surface for ${E(w.word)}. Typing and tiles are available as alternatives."></canvas><div class="g-actions">${B('Clear ink','ink-clear','btn-plain')}${B('I practised','ink-done','btn-primary')}${B('Use typing or tiles instead','word-build','btn-plain')}</div><p class="g-small">Writing is optional. The game records a practice visit, not handwriting accuracy. Drawings stay in this open activity and are not uploaded.</p>`;
shell(t.stage==='model'?'Meet a new word':t.stage==='build'?'Build what you hear':t.stage==='ink'?'A little printing practice':'A word for your toolkit',w.pattern.toUpperCase(),body);if(t.stage==='ink')initInk();A.icons();save();}
function wordCheck(){const t=wordTask,w=C.words[t.i];const typed=$('#g-word-input')?.value.trim().toLowerCase()||'';const answer=typed||t.built.map(x=>x.x).join('');if(!answer){$('.g-inline-message').textContent='Build a word with the tiles, or type it first.';return;}const r=g.wordRecords[t.i];r.attempts++;if(answer!==w.word){t.wrong=true;t.helped=true;t.showModel=true;t.built=[];t.typed='';r.helped++;schedule('w:'+t.i,false);drawWord();S.sfx('gentle');G.react('wrong');return;}
const clean=!t.wrong;if(clean&&!t.helped){r.independent++;if(!r.dates.includes(today()))r.dates.push(today());}t.reward=clean&&!r.firstPaid?10:0;if(!r.firstPaid)r.firstPaid=true;if(t.review&&clean&&g.reviews['w:'+t.i]?.paid!==today()){t.reward+=5;g.reviews['w:'+t.i].paid=today();}t.stage='success';g.practiceCount++;g.goals[today()]=g.goals[today()]||{stories:0,words:0,movement:false};g.goals[today()].words++;activity();schedule('w:'+t.i,clean);award(t.reward,clean?5:0);drawWord();S.celebrate(2);G.go(t.reward?2:1);if(clean)G.react('right');}
function initInk(){const c=$('#g-ink'),x=c.getContext('2d');function clear(){x.clearRect(0,0,c.width,c.height);x.fillStyle='#fffdf4';x.fillRect(0,0,c.width,c.height);x.strokeStyle='#b6c5b5';x.lineWidth=2;for(const y of [65,150,235]){x.setLineDash(y===150?[12,12]:[]);x.beginPath();x.moveTo(20,y);x.lineTo(980,y);x.stroke();}x.setLineDash([]);x.font=`${Math.min(175,850/C.words[wordTask.i].word.length*1.5)}px Nunito, sans-serif`;x.fillStyle='#d2dbcf';x.textBaseline='alphabetic';x.fillText(C.words[wordTask.i].word,40,230);}
clear();let down=false,last=null;const pos=e=>{const r=c.getBoundingClientRect();return {x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height};};c.onpointerdown=e=>{e.preventDefault();down=true;last=pos(e);c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(!down)return;e.preventDefault();const p=pos(e);x.beginPath();x.moveTo(last.x,last.y);x.lineTo(p.x,p.y);x.strokeStyle='#385b49';x.lineWidth=8;x.lineCap='round';x.stroke();last=p;};c.onpointerup=c.onpointercancel=()=>down=false;ink={clear};}
function camp(){active={kind:'camp'};const n=due(),go=g.goals[today()]||{stories:0,words:0,movement:false};const pages=Object.values(g.atlas).filter(Boolean).length;
$('#main').innerHTML=A.header('A LITTLE PRACTICE. A BIGGER WORLD.','Welcome to basecamp.','Your tools, discoveries, and next questions all have a home here.',B('For grown-ups','parent','btn-plain'))+`<section class="g-camp-hero"><img src="assets/bg-bc.webp" alt="A peaceful storybook forest by the water"><div><span class="eyebrow">YOUR ADVENTURE CONTINUES</span><h2>Keep the keys.<br>Grow the toolkit.</h2><p>Listening, asking, rereading, and taking a break are explorer skills.</p><div class="growth-chips"><span>${s.done} keys kept</span><span>${pages}/6 atlas pages</span><span>${g.trailPoints} trail points</span><span>${P.status().storageOK?'Autosave on this device':'Use a backup to keep progress'}</span></div></div></section><section class="g-camp-grid"><button class="g-camp-card" data-growth="words"><span>${I('puzzle')}</span><h3>Word forge</h3><p>Hear, build, spell, and try a little printing. ${wordLimit()} of 36 words open.</p></button><button class="g-camp-card" data-growth="review"><span>${I('repeat-2')}</span><h3>Clues to revisit</h3><p>${n.length?'A few earlier discoveries are ready to return.':'No review is due. You can still revisit a favourite.'}</p><small>Spaced practice, not a race.</small></button><button class="g-camp-card" data-growth="journal"><span>${I('heart-handshake')}</span><h3>My growth journal</h3><p>A feeling, a small thank-you, and something you cannot do yet.</p><small>Private on this device. Writing is optional.</small></button><button class="g-camp-card" data-growth="family"><span>${I('tent-tree')}</span><h3>Family field missions</h3><p>Take curiosity off-screen. Look, ask, notice, and explore safely together.</p></button></section><section class="g-casebook"><div class="section-heading"><h2>The atlas casebook</h2><span>${pages}/6 pages recovered</span></div><div class="g-case-grid">${CASES.map((c,i)=>`<button class="g-case-card ${g.atlas[i]?'complete':''}" data-growth="case" data-lv="${i}" ${s.done<(i+1)*3?'disabled':''}><img src="assets/bg-${W[i].id}.webp" alt=""><div><span>CASE ${i+1}</span><h3>${E(W[i].place)}</h3><small>${g.atlas[i]?'Page restored':s.done>=(i+1)*3?'Connect the clues':`${Math.max(0,(i+1)*3-s.done)} more keys open this case`}</small></div>${I(g.atlas[i]?'check':'notebook-tabs')}</button>`).join('')}</div></section><section class="g-today"><div><span class="eyebrow">A SMALL GOAL FOR TODAY</span><h3>One story. One word. A little movement.</h3><p>No streak to lose. Tomorrow is a fresh invitation.</p></div><div class="g-goal-row"><span class="${go.stories?'done':''}">${I(go.stories?'check':'book-open')} A story</span><span class="${go.words?'done':''}">${I(go.words?'check':'puzzle')} A word</span><button data-growth="break" class="${go.movement?'done':''}">${I(go.movement?'check':'footprints')} A movement break</button></div></section><section class="g-friend-cast"><div class="section-heading"><h2>Our local adventure cast</h2><span>Nicknames only</span></div><div class="g-cast-row">${P.data().roster.length?P.data().roster.map(r=>`<article><img src="assets/pokemon/${W[r.avatar].petId}.webp" alt=""><strong>${E(r.alias)}</strong><small>${E(r.role||'Fellow explorer')}</small></article>`).join(''):'<p>A grown-up can add friends as local story helpers. No online accounts or chat.</p>'}</div>${B('Choose a local explorer profile','profiles','btn-plain')}</section>`;A.icons();save();}
function review(){const n=due();active={kind:'review'};shell('A clue worth coming back to','REVISIT AFTER A DELAY',`<p>Remembering something after a break gives it another chance to stick. There is no countdown.</p><div class="g-review-list">${n.length?n.slice(0,8).map(([id,r])=>{const word=id.startsWith('w:');const p=id.slice(2).split('-').map(Number);return `<button data-growth="review-open" data-id="${id}"><span>${I(word?'puzzle':'search')}</span><div><strong>${word?'Word practice':C.quests[p[0]][p[1]].title}</strong><small>${word?C.words[+id.slice(2)].pattern:'Answer, then explain with evidence'} · up to 5 review XP once per day</small></div>${I('arrow-right')}</button>`;}).join(''):`<div class="g-note">No review is due just now. Missed work returns after two other activities or the next day. Successful work returns after 3, 7, 14, then 30 days.</div>${B('Explore the word bank','words','btn-primary')}`}</div>`);}
function journal(){G.say('coach-thanks',{once:true,cool:20000});const r=g.journal.find(x=>x.date===today())||{};active={kind:'journal'};shell('Today, in my own words','GROWTH IS A PRACTICE, NOT A PERFECT FEELING',`<p>All feelings are allowed. Pick a few words, tell a grown-up, or skip anything. There is no score for being cheerful.</p><label class="g-label">How does today feel?<select id="g-feeling">${['Not sure','Curious','Proud','Tired','Frustrated','Calm','Mixed'].map(x=>`<option ${r.feeling===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="g-label">One person, thing, or moment I appreciate<textarea id="g-gratitude" maxlength="240" placeholder="A helper, a quiet moment, a pet, a place...">${E(r.gratitude)}</textarea></label><label class="g-label">Something I cannot do yet, or want to try<textarea id="g-yet" maxlength="240" placeholder="I cannot ... yet. One small next step could be ...">${E(r.yet)}</textarea></label><label class="g-label">A strategy that helped<select id="g-strategy">${['I am still finding one','I asked for help','I listened and reread','I tried a new plan','I took a break','I used a model','I checked the evidence'].map(x=>`<option ${r.strategy===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="g-label">How ready do I feel for a small next step?<select id="g-confidence">${['Not sure yet','Ready with a helper','Ready to try','I would like a break'].map(x=>`<option ${r.confidence===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="g-actions">${B('Keep this journal page','journal-save','btn-primary')}${B('Not today','camp','btn-plain')}</div><p class="g-small">This is a personal check-in, not an emotional or clinical assessment. You can leave writing blank.</p>`);}
const OUTSIDE=[{id:'leaves',title:'Leaf detectives',text:'With a grown-up, notice three fallen leaves. Describe a shape, an edge, and a colour. Do not taste plants or pick from unfamiliar plants.'},{id:'kindness',title:'Notice a helper',text:'Think of someone who made your day easier. You can thank them, draw something, or quietly notice what they did. A thank-you is an invitation, not a requirement.'},{id:'newfood',title:'One new food question',text:'With a grown-up, ask about a food you have not explored before. Look, smell, or describe it. Check allergies. Tasting is always a choice.'},{id:'science',title:'Sink or float?',text:'With a grown-up and a shallow tray, predict whether two safe, washable objects float. Test one at a time, explain what happened, then dry the area. Never use plugged-in objects or small items around young children.'},{id:'walk',title:'A five-senses walk',text:'With a grown-up on a safe path, notice three things you can see and two sounds. You can skip any sense that feels uncomfortable. Leave wildlife and plants where they are.'},{id:'yet',title:'A different plan',text:'Choose one small, safe task that feels tricky. Tell a grown-up one strategy you could change. Try the new strategy if you want to, then talk about what you noticed.'}];
function family(){G.say('coach-friends',{once:true,cool:20000});active={kind:'family'};const ms=[...OUTSIDE,...P.data().missions];shell('Our family field book','REAL LIFE IS PART OF THE ADVENTURE',`<p>Choose a mission to do with a grown-up. No location tracking, photos, or uploads. A completed mission earns a journal stamp, not points for a particular feeling or food choice.</p><div class="g-family-grid">${ms.map(m=>`<button data-growth="family-open" data-id="${m.id}" class="g-family-card"><span>${I(g.completedMissions.includes(m.id)?'badge-check':m.kind==='story'?'book-open':'footprints')}</span><div><h3>${E(m.title)}</h3><p>${E(m.text.slice(0,150))}${m.text.length>150?'…':''}</p>${m.helper?`<small>Story helper: ${E(m.helper)}</small>`:''}</div></button>`).join('')}</div>${B('Add a family mission with a grown-up','parent','btn-plain')}`,'growth',true);}
function familyOpen(id){const m=[...OUTSIDE,...P.data().missions].find(x=>x.id===id);if(!m)return;if(m.kind==='story'){mini({key:'custom-'+m.id,title:m.title,eyebrow:'FAMILY STORY · '+(m.helper||'OUR ADVENTURE'),text:m.text,q:m.q,options:m.options,answer:m.answer,xp:10,done:()=>{if(!g.completedMissions.includes(id))g.completedMissions.push(id);save();},ending:'Your family discovery is in your mission book.'});return;}
active={kind:'family-mission',id};shell(m.title,'OFF-SCREEN MISSION · WITH A GROWN-UP',`<div class="g-passage"><p>${E(m.text)}</p></div>${B(I('volume-2')+' Read the mission','speak','btn-plain',`data-text="${E(m.text)}"`)}<div class="g-note">What did you notice? Tell, draw, type somewhere you choose, or show your grown-up. You can stop or adapt the mission at any point.</div><div class="g-actions">${B(g.completedMissions.includes(id)?'Stamp already kept':'Grown-up: mark our mission complete','family-done','btn-primary',`data-id="${id}" ${g.completedMissions.includes(id)?'disabled':''}`)}${B('Back to the field book','family','btn-plain')}</div>`);}
function breakFlow(){active=active||{kind:'break'};g.lastBreak=Date.now();S.stop();save();G.say('coach-break',{force:true});shell('A little reset','YOUR KEYS AND PROGRESS ARE SAFE',`<div class="g-break-orbit">${I('wind')}</div><h3>Pick a comfortable pause.</h3><div class="g-break-options">${['Stretch your hands or reach if comfortable.','Look away from the screen at something farther away.','Take a slow breath, or simply sit quietly.','Get water or move with your grown-up.'].map(x=>`<p>${E(x)}</p>`).join('')}</div><p>No timer. You decide when you are ready.</p><div class="g-actions">${B('I took a pause. Back to basecamp.','break-done','btn-primary')}${B('Keep my backup','save','btn-plain')}</div>`);}
function profiles(){active={kind:'profiles'};const d=P.data();shell('Who is exploring today?','LOCAL PROFILES · NO ONLINE MULTIPLAYER',`<p>Up to six explorers can take turns on this device. Each keeps separate keys, Pokémon, and learning history. Use nicknames, not full names.</p><div class="g-profile-grid">${d.profiles.map(p=>`<button data-growth="profile-switch" data-id="${p.id}" class="${d.active===p.id?'current':''}"><img src="assets/pokemon/${W[p.avatar].petId}.webp" alt=""><strong>${E(p.alias)}</strong><span>${p.state?.done||0} keys · ${d.active===p.id?'Current explorer':'Take a turn'}</span></button>`).join('')}</div><label class="g-label">New explorer nickname<input id="g-new-profile" maxlength="24" placeholder="A nickname only"></label>${B('Create a local explorer','profile-new','btn-green')}<p class="g-small">This does not connect devices or create live friend accounts. You can transfer this camp with a private backup.</p><div class="g-inline-message" role="status"></div>`);}
function parent(){active={kind:'parent'};const ls=Object.values(g.ledger).filter(r=>r.stage==='done'),clear=ls.filter(r=>r.wrongs===0),words=Object.values(g.wordRecords),events=ls.flatMap(r=>r.events||[]),first=ls.filter(r=>r.events?.length).map(r=>r.events[0]);const pct=first.length?Math.round(first.filter(r=>r.correct).length/first.length*100):null;const old=Math.max(0,s.done-ls.length),n=due();
$('#main').innerHTML=A.header('FAMILY CONTROL ROOM','A useful view of the journey.','Observations to discuss, not grades, diagnoses, or a measure of intelligence.',B('Back to basecamp','camp','btn-plain'))+`<div class="g-parent-note"><strong>Private by design.</strong> Progress, nicknames, and journal entries are stored in this browser when permitted. No game analytics, ads, chat, microphone recording, or automatic cloud sync. Backups contain learning history and journal text; keep them private. Browser clearing or a new device needs a backup.</div><div class="g-metric-grid"><article><strong>${s.done}/18</strong><span>Story keys kept</span><small>${old?`${old} earlier keys have no new-version assessment history.`:'Keys include supported completions.'}</small></article><article><strong>${pct===null?'—':pct+'%'}</strong><span>First question accuracy</span><small>${first.length} stories with recorded first attempts; not a reading test.</small></article><article><strong>${clear.length}/${ls.length}</strong><span>Answer + evidence first pass</span><small>Listening and requested clues are allowed.</small></article><article><strong>${words.filter(r=>r.dates.length>=2).length}</strong><span>Words recalled on 2+ days</span><small>A practice milestone, not “mastered”.</small></article></div><div class="g-parent-grid"><section class="g-panel"><h2>Learning controls</h2><label class="g-label">Question challenge<select id="g-tier"><option value="1" ${g.tier===1?'selected':''}>Guided: literal detail + evidence</option><option value="2" ${g.tier===2?'selected':''}>Explorer: inference + evidence</option><option value="3" ${g.tier===3?'selected':''}>Detective: two questions, each with evidence</option></select></label><label class="g-check"><input type="checkbox" data-g-setting="adaptive" ${g.adaptive?'checked':''}> Adjust question tier from recent first-pass accuracy</label><label class="g-check"><input type="checkbox" data-g-setting="tvEnabled" ${g.tvEnabled?'checked':''}> Allow optional Explorer TV clips (tap to load, internet needed)</label>${B(I('clapperboard')+' Preview Explorer TV library','exp-parent-library','btn-plain')}<label class="g-check"><input type="checkbox" data-g-setting="openWordBank" ${g.openWordBank?'checked':''}> Open all 36 word patterns</label><label class="g-label">Comfortable text size<input type="range" min=".9" max="1.4" step=".05" data-g-range="fontScale" value="${g.fontScale}"></label><label class="g-check"><input type="checkbox" data-g-setting="window" ${g.window?'checked':''}> Focus window around one reading card</label><label class="g-check"><input type="checkbox" data-g-setting="ruler" ${g.ruler?'checked':''}> Alternating reading-line guide</label><label class="g-label">Device voice pace<input type="range" min=".7" max="1.15" step=".05" data-g-range="rate" value="${g.rate}"></label><p class="g-small">Recorded narration has its own natural pace. Device voice availability varies.</p><label class="g-label">Offer a break after<select id="g-break-minutes">${[5,10,15,20,30].map(x=>`<option value="${x}" ${g.breakMinutes===x?'selected':''}>${x} minutes</option>`).join('')}</select></label>${B('Sound, spacing, and calmer runs','settings','btn-plain')}</section><section class="g-panel"><h2>Progress and review</h2><p>${n.length} items currently ready for review. Misses return after two other activities or a day; success schedules 3, 7, 14, then 30 days.</p><p>${g.practiceCount} word-building completions · ${g.printCount} optional printing-practice visits · ${g.journal.length} journal days.</p><p>${events.filter(e=>e.fast&&!e.correct).length} rapid incorrect commitments. A rapid incorrect commitment is one made within 2.5 seconds, or before the story cards were read. It costs 7 trail points instead of 5. Slow reading, narration, and help are never penalized, and speed is not a reading score.</p><div class="g-record-list">${ls.length?ls.map(r=>{const id=Object.entries(g.ledger).find(([,x])=>x===r)?.[0];return `<div><strong>${E(C.quests[+id[0]][+id[2]].title)}</strong><span>${r.wrongs?'Supported finish':r.hinted?'First pass with clue tool':'Answer and evidence first pass'} · ${r.xpEarned||0} XP</span></div>`;}).join(''):'<p>No new-version story records yet.</p>'}</div><div class="g-actions">${B('Open review','review','btn-green')}${B('Save and transfer','save','btn-plain')}</div></section><section class="g-panel"><h2>Add a story helper</h2><p>These are local fictional roles or friend nicknames, not connected accounts.</p><label class="g-label">Nickname<input id="g-friend-name" maxlength="24" placeholder="A friend’s nickname"></label><label class="g-label">Adventure role<input id="g-friend-role" maxlength="80" placeholder="Leaf scientist, boat builder, trail helper..."></label><label class="g-label">Companion picture<select id="g-friend-avatar">${W.map((w,i)=>`<option value="${i}">${w.pet}</option>`).join('')}</select></label>${B('Add to our local cast','friend-add','btn-green')}<div class="g-inline-message" id="g-friend-status" role="status"></div>${B('Local explorer profiles','profiles','btn-plain')}</section><section class="g-panel"><h2>Add a family mission</h2><label class="g-label">Mission type<select id="g-mission-kind"><option value="outside">Off-screen family activity</option><option value="story">A custom reading adventure</option></select></label><label class="g-label">Title<input id="g-mission-title" maxlength="70"></label><label class="g-label">Story or activity<textarea id="g-mission-text" maxlength="1600" placeholder="Connect the next adventure to home, a friend, or a family trip."></textarea></label><label class="g-label">Story helper<select id="g-mission-helper"><option value="">Our family</option>${P.data().roster.map(r=>`<option value="${E(r.alias)}">${E(r.alias)}</option>`).join('')}</select></label><details><summary>Custom reading question</summary><p class="g-small">Fill these for a reading adventure. The story must support one clearly correct answer.</p><label class="g-label">Question<input id="g-mission-q" maxlength="220"></label>${[0,1,2].map(i=>`<label class="g-label">Answer ${'ABC'[i]}<input id="g-mission-a${i}" maxlength="140"></label>`).join('')}<label class="g-label">Correct answer<select id="g-mission-correct"><option value="0">A</option><option value="1">B</option><option value="2">C</option></select></label></details>${B('Add to our family field book','mission-add','btn-primary')}<div id="g-mission-status" class="g-inline-message" role="status"></div></section></div><section class="g-panel g-evidence-panel"><h2>What the supports can do</h2><p>This game adapts explicit sound–letter modelling, cumulative word practice, short tasks, positive feedback, choice, worked examples, and spaced review. The overall game has not been clinically validated, and it is not treatment, a dyslexia assessment, or a substitute for an individualized teaching plan.</p><p>Ask Aiden’s teacher or reading specialist to choose an appropriate sequence and pace. Tracing is optional and is not automatically assessed. A readable typeface is a comfort choice, not a dyslexia intervention. Growth-journal check-ins are not clinical measurements.</p><p>Guidance: <a href="https://dyslexiaida.org/structuredliteracy/" target="_blank" rel="noopener">International Dyslexia Association: explicit, systematic literacy instruction</a>; <a href="https://www.cdc.gov/adhd/treatment/classroom.html" target="_blank" rel="noopener">CDC: classroom ADHD supports and positive behavioural strategies</a>; <a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/1" target="_blank" rel="noopener">IES: spaced learning, worked examples, retrieval, and explanatory questions</a>.</p><p>Fictional characters and events are set in real places. A food is an example from our story, not something everyone in that country eats. Pokémon belong to their respective owners; this is an unofficial personal fan-learning project.</p></section>`;A.icons();save();}
function saveModal(){active={kind:'save'};shell('Keep the whole camp safe','VERSION 3 · AUTOSAVE AND PRIVATE BACKUPS',`<div class="g-note">${P.status().storageOK?`Autosave is working in this browser. Last saved ${E(P.status().lastSaved)}. Reopening the same site and browser keeps this camp.`:'This window does not allow persistent browser storage. Download a backup or copy your code before closing. Open the standalone game for device autosave.'}</div><p>Cloud sync is not enabled. A PC and tablet have separate local saves; transfer the camp with a backup or code. Private browsing or clearing browser data can erase local progress.</p><div class="g-actions">${B(I('download')+' Download private JSON backup','backup-download','btn-primary')}${B(I('copy')+' Copy backup code','backup-copy','btn-plain')}</div><label class="g-label">Your whole-camp code<textarea id="save-code" readonly rows="3" spellcheck="false">${E(P.encode())}</textarea></label><details><summary>Restore or transfer an adventure</summary><p class="g-small">Restoring replaces this browser’s current camp, including all local profiles. Export a backup first. AWQ1 and AWQ2 restore only their earlier game data.</p><label class="g-label">Code or JSON<textarea id="resume-code" rows="3" placeholder="AWQ3 code, earlier AWQ1/AWQ2, or JSON" spellcheck="false"></textarea></label><label class="g-label">Or choose a private JSON backup<input id="g-import-file" type="file" accept=".json,application/json"></label>${B('Review this restore','import-review','btn-green')}<p id="save-error" class="inline-error" role="status"></p></details>${B('Start over for this explorer only','reset-review','btn-plain')}`);}
function download(text,name,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let pendingImport='';
function reviewImport(){const text=$('#resume-code')?.value.trim()||'';try{if(/^AWQ[12]-/.test(text)){if(text.length>2000)throw Error('This legacy code is too long.');const v=JSON.parse(atob(text.slice(5)));if(![1,2].includes(v.v)||!Number.isInteger(v.d)||v.d<0||v.d>18||!['short','long'].includes(v.r))throw Error('That earlier adventure code is not valid.');pendingImport=text;shell('Restore this earlier adventure?','REPLACES THE CURRENT EXPLORER’S GAME DATA',`<p>The earlier code contains <strong>${v.d} keys</strong>. New-version learning history for this explorer will be replaced. Other local profiles remain.</p><div class="g-actions">${B('Restore the earlier code','import-confirm','btn-primary')}${B('Cancel','save','btn-plain')}</div>`);}
else {const d=P.decode(text);pendingImport=text;shell('Replace this local camp?','RESTORE REVIEW · SAVE A BACKUP FIRST',`<p>This backup contains <strong>${d.profiles.length} local profiles</strong>, ${d.roster.length} cast members, and ${d.missions.length} custom missions.</p><ul>${d.profiles.map(p=>`<li>${E(p.alias)}: ${p.state.done} keys</li>`).join('')}</ul><p>It replaces this browser’s whole camp. It does not merge progress or update another device.</p><div class="g-actions">${B('Replace with this backup','import-confirm','btn-primary')}${B('Cancel','save','btn-plain')}</div>`);}}
catch(e){const m=e.message||'';$('#save-error').textContent=/atob|JSON|Unexpected|decode|string/i.test(m)||!m?'That code could not be read. Check that it is complete. Nothing was changed.':m;}}
function battle(i){if(s.done<(i+1)*3){A.toast('Collect three story keys here to enter the arena.');return;}let r=g.battleClean[i];if(!r||r.stage==='finished'){const old=r;r={round:0,stage:'intro',correct:0,tainted:!!old?.tainted,everPaid:!!old?.everPaid,attempt:(old?.attempt||0)+1,variant:old?.attempt%2?0:1,selected:-1,roundWrong:false};g.battleClean[i]=r;}
battleTask={i,r};active={kind:'battle'};selected=-1;G.say('coach-battle',{once:true,cool:15000});drawBattle();}
const BONUS=[{id:39,name:'Jigglypuff'},{id:63,name:'Abra'},{id:4,name:'Charmander'},{id:92,name:'Gastly'},{id:79,name:'Slowpoke'},{id:54,name:'Psyduck'}];
function drawBattle(){const t=battleTask,r=t.r,w=W[t.i],q=C.quests[t.i][Math.min(2,r.round)],x=q.questions[r.variant];const team=A.ownedTeam(),ally=team.find(p=>p.index===s.buddy)||team.find(p=>p.index===t.i)||team[0];
if(['question','evidence','move','review'].includes(r.stage)){if(S.state().action!=='battle')S.action('battle',.3);S.intensity(r.stage==='review'?.22:.32+.2*r.round+(r.stage==='evidence'?.08:0)+(r.stage==='move'?.15:0));}
const key='battle-'+t.i+'-'+r.attempt+'-'+r.round+'-'+r.stage;if(qSession!==key){qSession=key;questionAt=Date.now();selected=-1;}
let body='';if(r.stage==='intro')body=`<h3>Three moves. Clues, not quick guesses.</h3><p>Choose an answer, then prove it with a story detail. A missed answer becomes a guided practice move and closes the XP bonus. Keys never disappear.</p>${B('Begin the challenge','battle-begin','btn-primary')}`;
else if(r.stage==='question')body=`<div class="battle-question-head"><span class="eyebrow">ROUND ${r.round+1} · THINK, THEN COMMIT</span>${B(I('volume-2')+' Hear question','speak','btn-plain',`data-text="${E(x.q)}" data-audio="gq-${t.i}-${r.round}-${r.variant}"`)}</div><h3>${E(x.q)}</h3><div class="g-options battle-moves">${x.options.map((z,i)=>`<button class="g-option ${selected===i?'selected':''}" data-growth="battle-select" data-value="${i}" aria-pressed="${selected===i}"><b>${I('zap')}</b><span>${E(z)}</span></button>`).join('')}</div><div class="g-actions">${B('Power this move','battle-commit','btn-primary',selected<0?'disabled':'')}${B('Read the story clue','battle-clue','btn-plain')}</div>`;
else if(r.stage==='evidence')body=`<h3>Power it with evidence.</h3><p>${E(x.q)}</p><div class="g-options">${evidenceIds(x).map((idx,i)=>`<button class="g-option ${selected===idx?'selected':''}" data-growth="battle-evidence-select" data-value="${idx}" aria-pressed="${selected===idx}"><b>${i+1}</b><span>${E(q.sentences[idx])}</span></button>`).join('')}</div>${B('Use this evidence','battle-evidence','btn-primary',selected<0?'disabled':'')}`;
else if(r.stage==='review')body=`<div class="g-feedback">A practice move. Study the detail before the next round.</div><blockquote class="g-evidence">${E(q.sentences[x.evidence])}</blockquote><p>This supports <strong>${E(x.options[x.answer])}</strong>.</p><p class="g-small">This round will not count as a correct move. This country’s first-battle XP bonus stays closed, even after restarting.</p>${B('I studied the clue. Practice and move on.','battle-next','btn-green')}`;
else if(r.stage==='move')body=`<div class="g-feedback success">${I('sparkles')} Story-powered move. You matched the answer to its evidence.</div>${B(r.round===2?'See the result':'Next round','battle-next','btn-primary')}`;
else {const win=r.correct===3;body=`<div class="g-reward"><h3>${win?'A friendship badge earned.':'A useful practice battle.'}</h3><p>${win?`${BONUS[t.i].name} joins your team. ${r.xp||0} XP recorded.`:`${r.correct}/3 independent moves. Read the clues and try a fresh round when you want. No XP or badge for this practice battle.`}</p><div class="g-actions">${B(win?'Back to exploring':'Try a different question set','battle-exit','btn-primary')}${B('Return to basecamp','camp','btn-plain')}</div></div>`;}
A.showModal(`<section class="modal battle-modal g-battle" role="dialog" aria-modal="true" aria-labelledby="g-title">${A.closeButton()}<div class="battle-top"><div><span class="eyebrow">FRIENDSHIP ARENA · ${E(w.country)}</span><h2 id="g-title">${E(A.guides[t.i].name)}’s challenge</h2></div><span>${r.stage==='finished'?r.correct+'/3 story moves':`Round ${r.round+1}/3`}</span></div><div class="battle-stage ${r.stage==='move'&&s.motion?'ally-strike':''}"><img class="arena-bg" src="assets/arena.webp" alt=""><div class="fighter foe"><div class="nameplate"><strong>${BONUS[t.i].name}</strong><span>${Array.from({length:3},(_,i)=>I(i<3-r.correct?'star':'check')).join('')}</span></div><img src="assets/pokemon/${BONUS[t.i].id}.webp" alt="${BONUS[t.i].name}"></div><div class="fighter ally"><div class="nameplate"><strong>${E(ally.name)}</strong><span>Story power ${r.correct}/3</span></div><img src="assets/pokemon/${ally.id}.webp" alt="${E(ally.name)}"></div><div class="move-spark" aria-hidden="true"></div></div><div class="battle-panel">${body}</div></section>`,'growth-battle');S.boot();S.theme('battle');save();A.icons();}
function battleWrong(){const r=battleTask.r;r.tainted=true;r.roundWrong=true;r.stage='review';penalty(Date.now()-questionAt<2500);save();drawBattle();S.sfx('shield');}
function dash(i){if(i*3>s.done){A.toast('This trail opens after the earlier keys.');return;}const power=g.field[i]?.power||'none';A.showModal(`<section class="modal arcade-modal g-run" role="dialog" aria-modal="true" aria-label="Trail Dash">${A.closeButton()}<div class="arcade-title"><div><span class="eyebrow">TRAIL DASH · ${E(W[i].country)}</span><h2>Treasure on the trail</h2></div><div class="arcade-stats"><span>${I('gem')} <b data-run-stars>0</b> pts</span><span>${I('timer')} <b data-run-time>30</b>s</span></div></div><div class="run-wrap"><canvas width="960" height="400" aria-label="Jump to collect stars, gems, and nature tokens. Obstacles cost points and time."></canvas><div class="run-progress"><i data-run-bar></i></div><div class="run-start"><div><h3>Pick up wonder. Jump the trouble.</h3><p>Stars +10 · gems +25 · leaves +5 · clocks +3 seconds.<br>A collision costs 20 points and 2 seconds. Points never go below zero.</p><p>${power==='shield'?'Your field shield protects one collision.':power==='magnet'?'Your field magnet reaches more nearby treasure.':'A field mission can earn a shield or a pickup magnet.'}</p><button class="btn btn-primary" data-run-start data-initial-focus>${I('play')} Start the dash</button></div></div></div><div class="run-controls"><button class="btn btn-small btn-plain" data-run-pause>${I('pause')} Pause</button><button class="btn btn-primary jump-btn" data-run-jump>${I('arrow-up')} Jump</button><span class="run-help">Space, up arrow, tap the scene, or press Jump. Calm mode slows the trail.</span></div></section>`,'dash');
G.say('coach-run',{once:true,cool:15000});const buddy=A.ownedTeam().find(p=>p.index===s.buddy);A.setArcade(window.QuestGames.runner($('.g-run'),{petId:buddy?.id||W[i].petId,calm:s.calm,motion:s.motion,power,tier:g.tier,done:r=>{const old=g.runBest[i]||0,improve=Math.max(0,r.score-old),delta=Math.floor(improve/5);g.runBest[i]=Math.max(old,r.score);s.dashBest[i]=Math.max(s.dashBest[i],r.stars);s.dashPlayed[i]=true;const xp=Math.min(20,Math.floor(improve/20));award(xp,delta);activity();if(delta>0){S.celebrate(3);G.go(3);G.react('cheer');}else S.sfx('match');shell('Run complete',W[i].country+' · TREASURE TALLY',`<div class="g-run-tally"><strong>${r.score}<small>run score</small></strong><div><p>${r.stars} stars · ${r.gems} gems · ${r.leaves} leaves · ${r.clocks} clocks</p><p>${r.bumps} collisions · ${r.secondsLost} seconds lost · ${r.shielded} shield saves</p></div></div><p>${delta?`New personal best. Your camp gains +${delta} trail points and +${xp} XP from the improvement.`:'Your saved best stays safe. Only improving your best adds trail points and XP, so repeats cannot farm rewards.'}</p><div class="g-actions">${B('Run again','dash','btn-primary',`data-lv="${i}"`)}${B('Explore my route','path','btn-plain',`data-lv="${i}"`)}${B('Back to basecamp','camp','btn-plain')}</div>`);S.sfx('victory');}}));S.boot();S.theme('trail');A.icons();}
function settings(){A.settings();$$('[data-read]').forEach(b=>b.closest('.setting-group')?.remove());$('.modal-body')?.insertAdjacentHTML('beforeend',`<div class="g-note">Growth edition uses three richer reading cards per story in both reading modes. “Roomier reading” adjusts spacing; no story timer is used.</div><div class="g-actions">${B('Learning and family controls','parent','btn-plain')}${B('Save and transfer progress','save','btn-plain')}</div>`);A.icons();}
function help(){shell('An explorer’s toolkit','EXPLORE. EXPERIMENT. DECODE. DISCOVER.',`<div class="g-help-grid">${[['Explore the scene','Three short story cards take you somewhere new. Listening, slow reading, and breaks are always welcome.'],['Experiment in the Field Lab','Every scene has a hands-on science try: turn a dial, build a chain, hunt for clues, or crack a pattern. Wrong tries just give a friendly nudge.'],['Decode the clue','One plain question tells you what it is looking for: where, who, what, which, or how. Pick an answer, then tap the sentence that proves it.'],['Discover and collect','Each scene adds a card to your Nature Dex, earns a golden key, and sometimes unlocks new field gear. Ranks grow as your Dex fills up.'],['Watch Explorer TV','After a discovery you can load a short real-world video about the place, people, animal, or food. A grown-up can turn this off in For grown-ups.'],['Keep exploring','Build words, connect atlas clues, collect runner treasure, and power Pokémon moves with what you found. Rapid wrong guesses cost a few trail points; XP and keys are never removed. Autosave stays on this device.']].map(([t,b])=>`<div><h3>${t}</h3><p>${b}</p></div>`).join('')}</div><div class="g-actions">${B('Start my next adventure','continue','btn-primary')}${B('Visit basecamp','camp','btn-plain')}</div>`);}
function click(e){const b=e.target.closest('[data-growth]');if(!b||b.disabled)return;const act=b.dataset.growth,val=+b.dataset.value,lev=+(b.dataset.lv??s.level);S.sfx('tap');
if(act.startsWith('exp-')){X.click(b);return;}if(act==='peek'){if(active?.kind==='story'){const q=C.quests[active.level][active.n],x=storyQ();rec().hinted=true;save();$('.g-help-note')?.remove();$('.g-body')?.insertAdjacentHTML('beforeend',`<div class="g-note g-help-note"><strong>Story card ${Math.floor(x.evidence/2)+1}</strong><p>${E(q.chunks[Math.floor(x.evidence/2)])}</p>${B(I('volume-2')+' Read this card','speak','btn-plain',`data-audio="g-${active.level}-${active.n}-${Math.floor(x.evidence/2)}" data-text="${E(q.chunks[Math.floor(x.evidence/2)])}"`)}</div>`);A.icons();$('.g-help-note')?.scrollIntoView({block:'nearest',behavior:s.motion===false?'auto':'smooth'});}return;}if(act==='camp'){A.nav('camp');return;}if(act==='parent'){A.nav('parent');return;}if(act==='continue'){continueQuest();return;}if(act==='save'){saveModal();return;}if(act==='settings'){settings();return;}if(act==='speak'){speak(b.dataset.text||'',b.dataset.audio);return;}if(act==='pause-voice'){S.pauseVoice();return;}if(act==='break'){breakFlow();return;}if(act==='break-done'){g.goals[today()]=g.goals[today()]||{stories:0,words:0};g.goals[today()].movement=true;g.lastBreak=Date.now();save();A.nav('camp');return;}if(act==='words'){words();return;}if(act==='profiles'){profiles();return;}if(act==='family'){family();return;}if(act==='journal'){journal();return;}if(act==='review'){review();return;}if(act==='case'){caseMission(lev);return;}if(act==='path'){path(lev);return;}if(act==='dash'){dash(lev);return;}
if(act==='choose-path'){const t=active,i=t.level;g.paths[i]=val;save();const after=t.after;field(i);if(after)miniTask.after=after;return;}
if(act==='next-page'){const r=rec();r.readMs=(r.readMs||0)+Math.min(90000,Date.now()-viewAt);if(!r.seen.includes(r.page))r.seen.push(r.page);if(r.page<2)r.page++;else r.stage=(active.review||g.labs?.[active.id]?.done)?'check':'lab';selected=-1;save();drawStory();return;}
if(act==='prev-page'){rec().page=Math.max(0,rec().page-1);drawStory();return;}
if(act==='select-answer'||act==='select-evidence'){selected=val;drawStory();return;}
if(act==='commit-answer'){if(selected<0||rec().stage!=='check')return;const r=rec(),x=storyQ();if(selected!==x.answer)wrongAnswer('answer');else {r.events.push({date:today(),part:'answer',correct:true});r.stage='evidence';selected=-1;save();drawStory();S.sfx('match',.7);G.react('right');}return;}
if(act==='commit-evidence'){if(selected<0||rec().stage!=='evidence')return;if(selected!==storyQ().evidence)wrongAnswer('evidence');else {rec().events.push({date:today(),part:'evidence',correct:true});const r=rec();if(g.tier>=3&&!r.second&&!active.review&&r.wrongs===0){r.second=true;r.variant=r.variant===1?0:1;r.stage='check';selected=-1;save();drawStory();A.toast('One more detective question about this story.');}else finishKey();}return;}
if(act==='after-review'){const r=rec();r.variant=r.variant===1?0:1;r.stage=r.wrongs<2?'check':'guided';selected=-1;save();drawStory();return;}
if(act==='guided-evidence'){if(val===storyQ().evidence)finishKey();else $('.g-inline-message').textContent='Look for the exact sentence in the model above. This is practice; no points are being lost.';return;}
if(act==='reread'){if(active?.kind==='story'){active.reread=0;drawStory();}return;}
if(act==='reread-next'){if(active?.reread<2)active.reread++;else active.reread=null;drawStory();return;}
if(act==='reread-prev'){if(active?.reread>0)active.reread--;drawStory();return;}
if(act==='help'){if(active?.kind==='story'){const q=C.quests[active.level][active.n],x=storyQ();rec().hinted=true;save();$('.g-help-note')?.remove();$('.g-body')?.insertAdjacentHTML('beforeend',`<div class="g-note g-help-note"><strong>Clue tool — no penalty.</strong><p>${E(q.sentences[x.evidence])}</p>${B(I('volume-2')+' Read the clue card','speak','btn-plain',`data-audio="g-${active.level}-${active.n}-${Math.floor(x.evidence/2)}" data-text="${E(q.chunks[Math.floor(x.evidence/2)])}"`)}</div>`);A.icons();}return;}
if(act==='finish-story'){const t=active;if(t.review){A.nav('camp');return;}A.nav('area',t.level);if(t.n===2&&s.done>=(t.level+1)*3)A.petCelebration(t.level);else if(t.n<2&&s.done>=t.level*3+t.n+1)quest(t.n+1,t.level);return;}
if(act==='mini-select'){selected=val;g.goals[miniTask.key].choice=val;drawMini();return;}
if(act==='mini-commit'){const r=g.goals[miniTask.key];if(r.stage!=='ready'||selected<0)return;if(selected===miniTask.answer){finishMini();}else {r.wrong=true;r.stage='review';penalty(false);drawMini();}return;}
if(act==='mini-finish'){finishMini();return;}if(act==='mini-exit'){const cb=miniTask.after;if(cb)cb();else A.nav('area',s.level);return;}
if(act==='word-open'){wordOpen(val);return;}if(act==='word-build'){wordTask.stage='build';wordTask.built=[];wordTask.typed='';drawWord();return;}if(act==='word-listen'){const w=C.words[wordTask.i];speak(w.word+'. '+w.teach+'. '+w.meaning,'word-'+wordTask.i);return;}if(act==='word-model'){wordTask.showModel=!wordTask.showModel;wordTask.helped=true;drawWord();return;}if(act==='tile'){const item=wordTask.order.find(x=>x.id===val);if(item&&!wordTask.built.some(x=>x.id===val)&&wordTask.built.length<C.words[wordTask.i].tiles.length){wordTask.built.push(item);drawWord();}return;}if(act==='word-undo'){wordTask.built.pop();drawWord();return;}if(act==='word-check'){wordCheck();return;}if(act==='word-next'){wordOpen((wordTask.i+1)%wordLimit());return;}if(act==='word-ink'){wordTask.stage='ink';drawWord();return;}if(act==='ink-clear'){ink?.clear();return;}if(act==='ink-done'){g.printCount++;save();wordTask.stage='success';drawWord();return;}
if(act==='review-open'){const id=b.dataset.id;if(id.startsWith('w:'))wordOpen(+id.slice(2),true);else {const [i,n]=id.slice(2).split('-').map(Number);quest(n,i,true);}return;}
if(act==='journal-save'){const r={date:today(),feeling:$('#g-feeling').value,gratitude:$('#g-gratitude').value.trim(),yet:$('#g-yet').value.trim(),strategy:$('#g-strategy').value,confidence:$('#g-confidence').value};g.journal=g.journal.filter(x=>x.date!==today());g.journal.push(r);save();A.nav('camp');A.toast('Your journal page is kept. All feelings belong here.');return;}
if(act==='family-open'){familyOpen(b.dataset.id);return;}if(act==='family-done'){if(!g.completedMissions.includes(b.dataset.id))g.completedMissions.push(b.dataset.id);save();familyOpen(b.dataset.id);A.toast('A family field stamp is in your book.');return;}
if(act==='profile-switch'){P.switchProfile(b.dataset.id);return;}if(act==='profile-new'){try{P.newProfile($('#g-new-profile').value);}catch(e){$('.g-inline-message').textContent=e.message;}return;}
if(act==='friend-add'){try{if(!$('#g-friend-name').value.trim())throw Error('Add a nickname first.');P.addFriend({alias:$('#g-friend-name').value,role:$('#g-friend-role').value,avatar:+$('#g-friend-avatar').value});parent();$('#g-friend-status').textContent='Your helper is in the local cast and mission helper menu.';}catch(e){$('#g-friend-status').textContent=e.message;}return;}
if(act==='mission-add'){try{const kind=$('#g-mission-kind').value,title=$('#g-mission-title').value.trim(),text=$('#g-mission-text').value.trim(),q=$('#g-mission-q').value.trim(),options=[0,1,2].map(i=>$('#g-mission-a'+i).value.trim());if(!title||text.length<20)throw Error('Add a title and at least twenty characters of story or activity.');if(kind==='story'&&(!q||options.some(x=>!x)||new Set(options.map(x=>x.toLowerCase())).size!==3))throw Error('A reading adventure needs one question and three distinct answer choices.');P.addMission({kind,title,text,q,options,answer:+$('#g-mission-correct').value,helper:$('#g-mission-helper').value});parent();$('#g-mission-status').textContent='Your mission is in the family field book.';}catch(e){$('#g-mission-status').textContent=e.message;}return;}
if(act==='backup-download'){download(P.backup(),'aidens-world-quest-private-backup-'+today()+'.json');A.toast('Private backup download requested. Keep it somewhere safe.');return;}if(act==='backup-copy'){const input=$('#save-code');input.focus();input.select();if(navigator.clipboard?.writeText)navigator.clipboard.writeText(input.value).then(()=>A.toast('Backup code copied. It includes the whole local camp.')).catch(()=>A.toast('The code is selected. Use your device’s Copy command.'));else A.toast('The code is selected. Use your device’s Copy command.');return;}if(act==='import-review'){reviewImport();return;}if(act==='import-confirm'){try{if(/^AWQ[12]-/.test(pendingImport))P.legacy(pendingImport);else P.importData(pendingImport);g=s.g;A.toast('Adventure restored. Your next changes save on this device.');}catch(e){shell('The backup was not restored','NOTHING SHOULD BE LOST',`<p>${E(e.message)}</p>${B('Return to backups','save','btn-primary')}`);}return;}
if(act==='reset-review'){shell('Start over for this explorer?','OTHER LOCAL PROFILES WILL STAY',`<p>This removes ${E(P.status().profile)}’s keys, Pokémon, scores, journal, and learning history from this browser. Keep a private backup first.</p><div class="g-actions">${B('Erase this explorer and start again','reset-confirm','btn-primary')}${B('Cancel','save','btn-plain')}</div>`);return;}if(act==='reset-confirm'){P.resetActive();g=s.g;return;}
if(act==='battle-begin'){battleTask.r.stage='question';S.action('battle',.3);save();drawBattle();return;}if(act==='battle-select'||act==='battle-evidence-select'){selected=val;drawBattle();return;}if(act==='battle-commit'){if(battleTask.r.stage!=='question'||selected<0)return;const r=battleTask.r,x=C.quests[battleTask.i][r.round].questions[r.variant];if(selected===x.answer){r.stage='evidence';selected=-1;drawBattle();}else battleWrong();return;}if(act==='battle-evidence'){if(battleTask.r.stage!=='evidence'||selected<0)return;const r=battleTask.r,x=C.quests[battleTask.i][r.round].questions[r.variant];if(selected===x.evidence){r.correct++;r.stage='move';S.sfx('move');drawBattle();}else battleWrong();return;}if(act==='battle-clue'){const t=battleTask,r=t.r,q=C.quests[t.i][r.round],x=q.questions[r.variant];$('.g-battle-clue')?.remove();$('.battle-panel').insertAdjacentHTML('beforeend',`<blockquote class="g-evidence g-battle-clue">${E(q.sentences[x.evidence])}</blockquote>`);speak(q.chunks[Math.floor(x.evidence/2)],`g-${t.i}-${r.round}-${Math.floor(x.evidence/2)}`);return;}if(act==='battle-next'){const t=battleTask,r=t.r;r.round++;selected=-1;if(r.round>=3){r.round=2;r.stage='finished';if(r.correct===3){const first=!s.badges[t.i];s.badges[t.i]=true;r.xp=first&&!r.tainted&&!r.everPaid?60:0;r.everPaid=true;award(r.xp,r.xp);S.endAction();S.celebrate(4);G.go(4);G.react('cheer');}else S.endAction();activity();}else {r.stage='question';r.roundWrong=false;}save();drawBattle();return;}if(act==='battle-exit'){const t=battleTask;if(t.r.correct===3)A.nav('area',t.i);else battle(t.i);return;}
}
function change(e){const el=e.target;if(el.matches('[data-g-setting]')){g[el.dataset.gSetting]=el.checked;save();}if(el.id==='g-tier'){g.tier=+el.value;g.adaptive=false;save();parent();}if(el.id==='g-break-minutes'){g.breakMinutes=+el.value;save();}if(el.id==='g-import-file'&&el.files[0]){const f=el.files[0];if(f.size>700000){$('#save-error').textContent='That file is too large for a game backup.';return;}f.text().then(t=>{$('#resume-code').value=t;}).catch(()=>$('#save-error').textContent='The file could not be read.');}}
function input(e){X.input(e);const el=e.target;if(el.matches('[data-g-range]')){g[el.dataset.gRange]=+el.value;save();}if(el.id==='g-word-input'&&wordTask)wordTask.typed=el.value;}
function textState(){return {growth:{profile:P.status().profile,storage:P.status().storageOK?'local autosave':'backup required',trailPoints:g.trailPoints,tier:g.tier,atlas:Object.keys(g.atlas).filter(k=>g.atlas[k]),discoveries:Object.keys(g.discoveries||{}).filter(k=>g.discoveries[k]),tv:g.tvEnabled,field:g.field,reviewDue:due().map(([id])=>id),wordRecallDays:Object.fromEntries(Object.entries(g.wordRecords).map(([k,r])=>[C.words[k].word,r.dates.length])),active:active?.kind||null,story:active?.kind==='story'?{id:active.id,...rec(),question:storyQ().q,evidence:storyQ().evidence,selected}:null,word:active?.kind==='word'?{index:wordTask.i,stage:wordTask.stage,built:wordTask.built.map(x=>x.x).join(''),wrong:wordTask.wrong}:null,battle:active?.kind==='battle'?battleTask:null}};}
return {draw:()=>{if(active?.kind==='story')drawStory();},boot,queueSave,save,decorateTrail,decorateArea,decoratePassport,camp,parent,quest,path,guide,caseMission,words,saveModal,help,battle,dash,settings,textState,continueQuest};
})();
